#!/usr/bin/env bash
# Read-only: MR-100 check on existing priced quotes in QA - plan lines with quote Location Count, quantity, list, net and volume adjustment
q() { sf data query --query "$1" --target-org target --json 2>/dev/null | jq -c '[.result.records[]? | del(.attributes)]'; }
q "SELECT Quote.QuoteNumber, Quote.Location_count__c, Quote.Account.Name, Quote.RLM_TermMonths__c, Product2.ProductCode, Quantity, BillingFrequency, ListPrice, NetUnitPrice FROM QuoteLineItem WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT') AND NetUnitPrice != null AND Quote.Name != 'QA TEST MR-100' ORDER BY CreatedDate DESC LIMIT 25" | jq -c '.[] | [.Quote.QuoteNumber, .Quote.Account.Name, "loc", .Quote.Location_count__c, "term", .Quote.RLM_TermMonths__c, .Product2.ProductCode, "qty", .Quantity, .BillingFrequency, .ListPrice, .NetUnitPrice]'
echo "VOLUME ADJ $(q "SELECT QuoteLineItem.Quote.QuoteNumber, QuoteLineItem.Product2.ProductCode, AdjustmentSource, AdjustmentType, AdjustmentValue FROM QuoteLinePriceAdjustment WHERE QuoteLineItem.Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT') ORDER BY CreatedDate DESC LIMIT 30" | jq -c '[.[] | [.QuoteLineItem.Quote.QuoteNumber, .QuoteLineItem.Product2.ProductCode, .AdjustmentSource, .AdjustmentValue]]')"
